class Solution {
    int dfs(int idx, std::vector<int>& inv, const std::vector<std::string>& words, const std::vector<int>& score) {
        if (idx == words.size()) return 0;
        int res = dfs(idx + 1, inv, words, score);

        bool canTake = true;
        int wordScore = 0;
        std::vector<int> req(26, 0);
        for (char c : words[idx]) {
            req[c - 'a']++;
            wordScore += score[c - 'a'];
            if (req[c - 'a'] > inv[c - 'a']) canTake = false;
        }
        if (canTake) {
            for (int i = 0; i < 26; ++i) inv[i] -= req[i];
            res = std::max(res, wordScore + dfs(idx + 1, inv, words, score));
            for (int i = 0; i < 26; ++i) inv[i] += req[i];
        }
        return res;
    }
public:
    int maxScoreWords(std::vector<std::string>& words, std::vector<char>& letters, std::vector<int>& score) {
        std::vector<int> inv(26, 0);
        for (char c : letters) inv[c - 'a']++;
        return dfs(0, inv, words, score);
    }
};

class Solution {
    int dfs(int idx, int[] inv, String[] words, int[] score) {
        if (idx == words.length) return 0;
        int res = dfs(idx + 1, inv, words, score);

        boolean canTake = true;
        int wordScore = 0;
        int[] req = new int[26];
        for (char c : words[idx].toCharArray()) {
            req[c - 'a']++;
            wordScore += score[c - 'a'];
            if (req[c - 'a'] > inv[c - 'a']) canTake = false;
        }
        if (canTake) {
            for (int i = 0; i < 26; i++) inv[i] -= req[i];
            res = Math.max(res, wordScore + dfs(idx + 1, inv, words, score));
            for (int i = 0; i < 26; i++) inv[i] += req[i];
        }
        return res;
    }
    public int maxScoreWords(String[] words, char[] letters, int[] score) {
        int[] inv = new int[26];
        for (char c : letters) inv[c - 'a']++;
        return dfs(0, inv, words, score);
    }
}

var maxScoreWords = function(words, letters, score) {
    const inv = new Array(26).fill(0);
    for (const c of letters) inv[c.charCodeAt(0) - 97]++;

    const dfs = (idx, invArr) => {
        if (idx === words.length) return 0;
        let res = dfs(idx + 1, invArr);

        let canTake = true;
        let wordScore = 0;
        const req = new Array(26).fill(0);
        for (let i = 0; i < words[idx].length; i++) {
            const code = words[idx].charCodeAt(i) - 97;
            req[code]++;
            wordScore += score[code];
            if (req[code] > invArr[code]) canTake = false;
        }
        if (canTake) {
            for (let i = 0; i < 26; i++) invArr[i] -= req[i];
            res = Math.max(res, wordScore + dfs(idx + 1, invArr));
            for (let i = 0; i < 26; i++) invArr[i] += req[i];
        }
        return res;
    };
    return dfs(0, inv);
};
